---@class CommonCalculationNode
---@field Env                           	CommonCalculationNode                   
---@field controller                    	Engine.Modules.LuaBehaviour             
---@field InputField                    	TMPro.TMP_InputField                    
---@field BtnAdd                        	UnityEngine.RectTransform               
---@field BtnReduce                     	UnityEngine.RectTransform               
local CommonCalculationNode = Class('CommonCalculationNode')
local EasyTouch =  CS.HedgehogTeam.EasyTouch.EasyTouch
local QuickLongTapType = typeof(CS.HedgehogTeam.EasyTouch.QuickLongTap)
local KTool = CS.Engine.Lib.KTool

function CommonCalculationNode:__init()
    self.curNum = 1
    self.maxNum = 999
    self.minNum = 1
    self.maxTip = ""
end

function CommonCalculationNode:__delete()
    self.curNum = nil
    self.maxNum = nil
    self.minNum = nil
    self.maxTip = nil
    EasyTouch.instance.enableUIMode = false
    EasyTouch.SetUICompatibily( true)
end

function CommonCalculationNode:Awake()
    self:AddUIClick()
end

function CommonCalculationNode:AddUIClick()
    self.longAddTapComp = KTool.GetOrAddComponent(self.BtnAdd.gameObject, QuickLongTapType)
    self.longAddTapComp.onLongTap:AddListener(Bind(self, self.OnBtnAddPointDown))

    self.longReduceTapComp = KTool.GetOrAddComponent(self.BtnReduce.gameObject, QuickLongTapType)
    self.longReduceTapComp.onLongTap:AddListener(Bind(self, self.OnBtnReducePointDown))

    self.InputField.onValueChanged:AddListener(Bind(self, self.InputFieldListener))

    SetButtonAction(self.BtnAdd.gameObject,Bind(self,self.OnAddBtnClick))
    SetButtonAction(self.BtnReduce.gameObject,Bind(self,self.OnDelBtnClick))
end
---@
function CommonCalculationNode:SetParams(callBack,curNum,minNum,maxNum,maxTip)
    self.callBack = callBack
    self.curNum = curNum
    self.minNum = minNum
    self.maxNum = maxNum
    self.maxTip = maxTip
    self.InputField.text = self.curNum
end

function CommonCalculationNode:OnBtnAddPointDown()
    self.curNum = self.curNum + 1
    if self.curNum > self.maxNum then
        self.curNum = self.maxNum
        return
    end
    self.InputField.text = self.curNum
    if self.callBack then
        self.callBack(self.curNum)
    end
end

function CommonCalculationNode:OnBtnReducePointDown()
    self.curNum = self.curNum - 1
    if self.curNum < self.minNum then
        self.curNum = self.minNum
        return
    end
    self.InputField.text = self.curNum
    if self.callBack then
        self.callBack(self.curNum)
    end
end

function CommonCalculationNode:InputFieldListener()
    local num = tonumber(self.InputField.text) or self.curNum
    self.curNum = num
    if not isNull(self.curNum) then
        if self.curNum > self.maxNum then
            self.curNum = self.maxNum
        end
        if self.curNum <= self.minNum then
            self.curNum = self.minNum
        end
        self.InputField.text = self.curNum
        if self.callBack then
            self.callBack(self.curNum)
        end
    end
end

function CommonCalculationNode:OnAddBtnClick()
    self.curNum = self.curNum + 1
    if self.curNum > self.maxNum then
        self.curNum = self.maxNum
        GameUtils.Toast(self.maxTip)
        return
    end
    self.InputField.text = self.curNum
    if self.callBack then
        self.callBack(self.curNum)
    end
end

function CommonCalculationNode:OnDelBtnClick()
    self.curNum = self.curNum - 1
    if self.curNum < self.minNum then
        self.curNum = self.minNum
        return
    end
    self.InputField.text = self.curNum
    if self.callBack then
        self.callBack(self.curNum)
    end
end

function CommonCalculationNode:GetInputNum()
    return self.curNum
end

function CommonCalculationNode:SetInputText(num)
    self.curNum = num
    self.InputField.text = self.curNum
end

function CommonCalculationNode:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
end

return CommonCalculationNode